const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const wanted = ($('Settings').first().json.actTypes || []).map(norm);
const pick = (text, label, next) => {
  const m = String(text || '').match(new RegExp(label + ':\\s*(.*?)\\.\\s*(?:' + next + '):', 'i'));
  return m ? m[1].trim() : '';
};
return $input.all().map(({ json: e }) => {
  const acts = e.acts || [];
  const main = acts.find(a => wanted.some(w => norm(a.type).includes(w))) || acts[0] || {};
  // Drop the PDF page footer that sometimes lands inside a notice
  const d = String(main.details || '').replace(/\s*BOLET[IÍ]N OFICIAL DEL REGISTRO MERCANTIL.*?Verificable en https:\/\/www\.boe\.es\s*/gi, ' ');
  const capital = (d.match(/Capital:\s*([\d.,]+\s*Euros)/i) || [])[1] || '';
  return { json: {
    date: e.date,
    province: e.province,
    companyName: e.companyName,
    registryNumber: e.registryNumber,
    actType: main.type || '',
    startOfOperations: ((d.match(/Comienzo de operaciones:\s*([\d.]+)/i) || [])[1] || '').replace(/\.$/, ''),
    corporatePurpose: pick(d, 'Objeto social', 'Domicilio|Capital'),
    address: pick(d, 'Domicilio', 'Capital') || (d.match(/Domicilio:\s*(.*?)\.?\s*$/i) || [])[1] || '',
    capital,
    otherActs: acts.filter(a => a !== main).map(a => a.type).join(', '),
    bormeId: e.bormeId,
    sourceUrl: e.sourceUrl,
  } };
});

const rows = $('One row per company').all().map(i => i.json);
const byProvince = {};
for (const r of rows) byProvince[r.province] = (byProvince[r.province] || 0) + 1;
const day = rows[0]?.date || $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const label = rows.length + ' ' + (rows.every(r => /constituci/i.test(r.actType)) ? 'new ' : '') + (rows.length === 1 ? 'company' : 'companies');
const html = '<p><b>' + label + '</b> in BORME of ' + esc(day) + ': '
  + Object.entries(byProvince).map(([p, n]) => esc(p) + ' ' + n).join(', ') + '</p><ul>'
  + rows.slice(0, 25).map(r => '<li>' + esc(r.companyName) + ' (' + esc(r.province) + ') - ' + esc(r.capital) + ' - ' + esc(r.corporatePurpose).slice(0, 140) + '</li>').join('')
  + '</ul>' + (rows.length > 25 ? '<p>...and ' + (rows.length - 25) + ' more in the sheet.</p>' : '');
return [{ json: { subject: 'BORME ' + day + ': ' + label, html } }];
